}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
static void buildFromNDXAllianceTree()
{
    NDXAllianceTree             nDXAllianceTree;
    NDXAllianceTree             nDXAllianceTreeGrp;
    NDXAllianceTreeCustomer     nDXAllianceTreeCustomer;
    CustTable                   custTable;
    RecordInsertList            rilNDXAllianceTreeCustomer;
    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    str                         qValueString;
    NDXChilds                   childs;
    CompanyId                   company;
    ;
    // bestehende Einträge löschen
    delete_from nDXAllianceTreeCustomer;

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/18.12.2014
    while select Company from nDXAllianceTreeGrp group by Company
    {
        company = NDXHelperCommon::NDXCompanys2CompanyId(nDXAllianceTreeGrp.Company);
        changecompany(company)
        {
            nDXAllianceTree = null;
            //<-- NDX/PAFFH/NDX_TASK1235003633/18.12.2014
            rilNDXAllianceTreeCustomer = new RecordInsertList(tableNum(NDXAllianceTreeCustomer));
            // für jeden Unterverband die Debitoren ermitteln
            while select forUpdate nDXAllianceTree where nDXAllianceTree.Company == nDXAllianceTreeGrp.Company
            {
                // Unterverbände des Unterverbands ermitteln
                qValueString = NDXAllianceTree::conSubAlliance2QueryValue(nDXAllianceTreeGrp.Company, nDXAllianceTree.Parent, nDXAllianceTree.Child);

                q       = new Query();
                qbds    = q.addDataSource(tablenum(CustTable));
                qbds.addRange(fieldnum(CustTable, KCS_TOSId)).value(qValueString);
                qr      = new QueryRun(q);
                childs  = 0;
                while (qr.next())
                {
                    custTable = qr.get(tablenum(CustTable));
                    // Kunde darf keinen (Sub-)Verband darstellen
                    if (nDXAllianceTree::findChild(nDXAllianceTreeGrp.Company, custTable.AccountNum))
                    {
                        continue;
                    }
                    nDXAllianceTreeCustomer = null;
                    nDXAllianceTreeCustomer.initFromNDXAllianceTree(nDXAllianceTree);
                    nDXAllianceTreeCustomer.AllianceSub    = custTable.KCS_TOSId;
                    nDXAllianceTreeCustomer.Level          = NDXAllianceTree::getLevel(nDXAllianceTreeCustomer.AllianceSub);
                    nDXAllianceTreeCustomer.AccountNum     = custTable.AccountNum;
                    nDXAllianceTreeCustomer.Party          = custTable.Party;
                    rilNDXAllianceTreeCustomer.add(nDXAllianceTreeCustomer);
                    ++childs;
                }
                ttsbegin;
                nDXAllianceTree.Childs = childs;
                nDXAllianceTree.update();
                ttscommit;
            }
            rilNDXAllianceTreeCustomer.insertDatabase();
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "nDXAllianceTree">NDXAllianceTree</param>
void initFromNDXAllianceTree(NDXAllianceTree nDXAllianceTree)
{
    ;
    this.Alliance       = NDXAllianceTree.Alliance;
    this.Parent         = NDXAllianceTree.Parent;
    this.Child          = NDXAllianceTree.Child;
    this.VersionDate    = nDXAllianceTree.modifiedDateTime;
    this.Company        = nDXAllianceTree.Company;                               // 1.1: NDX/PAFFH/NDX_TASK1235003633/18.12.2014
}
